///|
test "grader confirms success cleanup" {
  assert_eq(@cleanup_order.trace(false, false), ["inner-body", "inner-always", "after-inner", "done", "outer-always"])
}

///|
test "grader confirms early propagated error cleanup" {
  assert_eq(@cleanup_order.trace(true, false), ["inner-body", "inner-always", "inner-error", "outer-always", "outer-error-first", "caught"])
}

///|
test "grader confirms error after successful inner block" {
  assert_eq(@cleanup_order.trace(false, true), ["inner-body", "inner-always", "after-inner", "outer-error-second", "outer-always", "outer-error-first", "caught"])
}
